# -*- coding: utf-8 -*-
# Python 3.9 토크나이저가 31행의 초장문 HTML 줄에서 한글 멀티바이트를 잘라 읽는 문제가 있어
# 인코딩을 명시한다. 파일 자체는 정상 UTF-8이다.
"""Generate offline SVG relationship explorer + Mermaid ERDs from schema metadata."""
import json,html,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];p=ROOT/'docs/db/schema-metadata/schema.json';d=json.loads(p.read_text());out=ROOT/'docs/architecture/erd';out.mkdir(parents=True,exist_ok=True)
mods={'core':'CORE 인증·공간·운영','mes':'MES 생산','erp':'ERP 판매·출하·회계','fems':'FEMS 에너지','qms':'QMS 품질','wms':'WMS 창고','bems':'BEMS 건물','spc':'SPC 공정관리'}
ts={t['name']:t for t in d['tables']}
def ident(n):return n.replace('.','_')
def mermaid(mod):
 names=set(ts) if mod=='all' else {n for n in ts if n.startswith(mod+'.')}
 rs=[r for r in d['relations'] if r['source'] in names]
 shown=names|{r['target'] for r in rs};lines=['erDiagram']
 for name in sorted(shown):
  t=ts[name];lines.append('  '+ident(name)+' {')
  for c in t['columns']:
   tags=[]
   if any(k['table']==name and k['kind']=='PK' and c['name'] in k['columns'] for k in d['constraints']):tags.append('PK')
   if any(r['source']==name and c['name'] in r['columns'] for r in d['relations']):tags.append('FK')
   typ=c['type'].split('(')[0].replace(' ','_')
   lines.append('    '+typ+' '+c['name']+(' '+','.join(tags) if tags else '')+' "'+c['label'].replace('"','')+(' NULL' if c['nullable'] else '')+'"')
  lines.append('  }')
 for r in rs:
  nullable=any(next(c for c in ts[r['source']]['columns'] if c['name']==x)['nullable'] for x in r['columns'])
  unique=any(k['table']==r['source'] and k['kind'] in ['PK','UK'] and set(k['columns'])<=set(r['columns']) for k in d['constraints'])
  lines.append(f"  {ident(r['target'])} {'|o' if nullable else '||'}..{'o|' if unique else 'o{'} {ident(r['source'])} : \"{','.join(r['columns'])}\"")
 return '\n'.join(lines)+'\n'
for obsolete in ['learning', 'process_map']:
 (out/(obsolete+'.mmd')).unlink(missing_ok=True)
for m in ['all',*mods]: (out/(m+'.mmd')).write_text(mermaid(m))
data=json.dumps(d,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EIP 모듈별 DB 관계도</title><style>
*{box-sizing:border-box}body{margin:0;background:#F7F7F6;color:#1A1C1E;font:15px -apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo",sans-serif}header{padding:28px 4%;border-bottom:1px solid #ddd;background:white}h1{font-size:26px;margin:8px 0}p{line-height:1.7;color:#59616a}nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}button{font:inherit;padding:10px 15px;border:1px solid #d9dddf;background:white;border-radius:8px;cursor:pointer;color:#1F2D3D}button[aria-pressed=true]{background:#1F2D3D;color:white}button:focus-visible,input:focus-visible{outline:3px solid #61758b;outline-offset:3px}main{padding:20px 4%}.bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.view{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;margin-top:20px}.canvas{overflow:auto;border:1px solid #d9dddf;border-radius:12px;background:white;max-height:75vh}aside{background:white;padding:20px;border:1px solid #d9dddf;border-radius:12px;max-height:75vh;overflow:auto}svg{display:block}svg text{font-family:Arial,"Apple SD Gothic Neo",sans-serif}pre{white-space:pre-wrap;font-size:12px;line-height:1.7}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:9px 6px;text-align:left;border-bottom:1px solid #e4e6e8;overflow-wrap:anywhere}small{color:#68717a}.edge{fill:none;stroke:#8898a6;stroke-width:1.3;opacity:.25}.node{cursor:pointer}.node:focus rect{stroke:#1F2D3D;stroke-width:3}.external rect{fill:#f4f3ef;stroke-dasharray:5 3}input{padding:10px;border:1px solid #ddd;border-radius:7px}a{color:#1F2D3D}@media(max-width:900px){.view{grid-template-columns:1fr}aside{max-height:50vh}}
</style><header><small>FACTORY STUDIO / DESIGN v__VERSION__</small><h1>독립 솔루션별 데이터 관계</h1><p>전체 구조 → 모듈 선택 → 테이블 선택 순서로 살펴보세요. 테이블을 누르면 키·컬럼과 연결 관계가 나타납니다.<br>설계 초안 · 실제 DB 미적용. 선은 외래키 참조이며 업무 실행 순서가 아닙니다. 점선 테두리는 다른 모듈의 참조 테이블입니다.</p><nav id="nav"></nav></header><main><div class="bar"><b id="title"></b><label>확대 <input id="zoom" aria-label="다이어그램 확대" type="range" min="60" max="160" value="100" oninput="resize()"></label><button onclick="select(null)">선택 해제</button><label><input id="scope" type="checkbox" onchange="draw()">공간·세대 FK 표시</label></div><div class="view"><div class="canvas" id="canvas"></div><aside id="detail"><h2>테이블을 선택하세요</h2></aside></div><p>관계 표시는 실제 메타데이터에서 생성됩니다. 모듈 그림은 해당 모듈에서 나가는 FK와 직접 참조 대상을 포함합니다. 1:N/선택 관계의 전체 명세는 Mermaid 원본과 Excel 관계 시트에도 수록했습니다.</p></main><script>const d=__DATA__;const modules=__MODS__;
let mode='overview',shown=[],relations=[];const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const table=n=>d.tables.find(t=>t.name===n);
const nav=document.getElementById('nav');for(const [key,label] of [['overview','EIP 전체 구조'],['all','전체 ERD'],...Object.entries(modules)]){const b=document.createElement('button');b.textContent=label;b.dataset.mode=key;b.onclick=()=>{mode=key;draw()};nav.append(b)}
function cardFields(t){const fk=new Set(d.relations.filter(r=>r.source===t.name).flatMap(r=>r.columns));return t.columns.filter(c=>c.name==='id'||fk.has(c.name)).slice(0,5).map(c=>`${c.name==='id'?'PK':'FK'}  ${c.name}${c.nullable?' ?':''}`)}
function resize(){const s=document.querySelector('#canvas svg');if(s)s.style.width=(Number(document.getElementById('zoom').value)/100*Number(s.dataset.width))+'px'}
function draw(){document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));const scope=document.getElementById('scope').checked;let body='',edges='';
if(mode==='overview'){document.getElementById('title').textContent='Factory Studio / '+d.tables.length+'개 테이블 · '+Object.keys(modules).length+'개 스키마';shown=Object.keys(modules);relations=[];body='<rect x="390" y="25" width="260" height="66" rx="10" fill="#1F2D3D"/><text x="520" y="64" text-anchor="middle" fill="white" font-size="21">EIP 앱 런처</text>';
shown.forEach((m,i)=>{const x=30+(i%3)*345,y=160+Math.floor(i/3)*165;body+=`<path d="M520 92 V120 H${x+150} V${y}" class="edge"/><g class="node" tabindex="0" role="button" aria-label="${modules[m]} 열기" onclick="mode='${m}';draw()" onkeydown="if(event.key==='Enter'){mode='${m}';draw()}"><rect x="${x}" y="${y}" width="300" height="115" rx="10" fill="#F7F7F6" stroke="#cbd1d5"/><text x="${x+20}" y="${y+37}" font-size="20" fill="#1F2D3D">${modules[m]}</text><text x="${x+20}" y="${y+70}" font-size="14">${d.tables.filter(t=>t.name.startsWith(m+'.')).length}개 테이블</text><text x="${x+20}" y="${y+93}" font-size="12" fill="#65717b">모듈 ERD 보기 →</text></g>`});document.getElementById('canvas').innerHTML=`<svg data-width="1080" width="1080" viewBox="0 0 1080 665">${body}</svg>`;document.getElementById('detail').innerHTML='<h2>독립 솔루션과 공통 인증</h2><p>MES·ERP·FEMS·QMS·WMS·BEMS는 자체 업무 마스터를 소유합니다. 솔루션 간 업무 FK는 없고, 다른 솔루션 값은 읽기 전용 조회로 스냅샷만 보관합니다.</p><p>CORE는 인증·공간·세대·운영만 소유합니다. 업무 스키마는 공간·세대 앵커만 참조합니다.</p><p>FEMS 생산량은 독립 입력입니다. 도움말·흐름 맵과 SCM 설명 카드는 정적 파일입니다.</p><small>이 화면의 EIP→모듈 선은 구성 관계입니다.</small>';resize();return}
const owned=d.tables.filter(t=>mode==='all'||t.name.startsWith(mode+'.')).map(t=>t.name);relations=d.relations.filter(r=>owned.includes(r.source)&&(scope||!['core.workspace','core.data_generation'].includes(r.target)));shown=[...new Set([...owned,...relations.map(r=>r.target)])];const cols=3,w=1120,cell=365,h=220;const positions=Object.fromEntries(shown.map((n,i)=>[n,{x:20+(i%cols)*cell,y:25+Math.floor(i/cols)*h}]));
relations.forEach((r,i)=>{const a=positions[r.source],b=positions[r.target];const x=a.x+155,y=a.y+170,tx=b.x+155,ty=b.y;edges+=`<path id="e${i}" data-source="${r.source}" data-target="${r.target}" class="edge" d="M${x} ${y} C${x} ${y+40},${tx} ${ty-40},${tx} ${ty}" marker-end="url(#arrow)"/>`});
shown.forEach(n=>{const t=table(n),p=positions[n],external=!owned.includes(n);body+=`<g class="node ${external?'external':''}" data-table="${n}" tabindex="0" role="button" aria-label="${n} ${t.label}" onclick="select('${n}')" onkeydown="if(event.key==='Enter')select('${n}')"><rect x="${p.x}" y="${p.y}" width="320" height="174" rx="9" fill="white" stroke="#c4ccd3"/><text x="${p.x+14}" y="${p.y+28}" font-size="14" font-weight="bold" fill="#1F2D3D">${n}</text><text x="${p.x+14}" y="${p.y+50}" font-size="12" fill="#66717c">${esc(t.label)}${external?' · 외부 참조':''}</text>${cardFields(t).map((v,i)=>`<text x="${p.x+14}" y="${p.y+75+i*17}" font-size="12">${v}</text>`).join('')}<text x="${p.x+14}" y="${p.y+162}" font-size="11" fill="#66717c">전체 ${t.columns.length}개 컬럼 · 선택하여 상세 보기</text></g>`});
document.getElementById('title').textContent=(mode==='all'?'전체 ERD':modules[mode])+' / '+owned.length+'개 소유 테이블';document.getElementById('canvas').innerHTML=`<svg data-width="${w}" width="${w}" viewBox="0 0 ${w} ${Math.ceil(shown.length/cols)*h+35}"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#8898a6"/></marker></defs>${edges}${body}</svg>`;resize();select(null)}
function select(n){document.querySelectorAll('.edge').forEach(e=>{const active=n&&(e.dataset.source===n||e.dataset.target===n);e.style.opacity=n?(active?'1':'.06'):'.25';e.style.strokeWidth=active?'2.5':'1.3'});document.querySelectorAll('[data-table] rect').forEach(e=>{e.style.stroke=e.parentElement.dataset.table===n?'#1F2D3D':'#c4ccd3';e.style.strokeWidth=e.parentElement.dataset.table===n?'3':'1'});if(!n){document.getElementById('detail').innerHTML='<h2>테이블을 선택하세요</h2><p>PK/FK 일부를 도식에 표시했습니다. 선택하면 전체 컬럼과 실제 관계를 확인할 수 있습니다.</p><p>공간·세대 FK는 기본 숨김입니다. 상단 체크박스로 모두 표시할 수 있습니다.</p>';return}const t=table(n);const rs=d.relations.filter(r=>r.source===n||r.target===n);document.getElementById('detail').innerHTML=`<h2>${esc(t.label)}</h2><p>${n}</p><small>${t.scope} / ${t.retention}</small><h3>전체 컬럼</h3><table><tr><th>이름</th><th>타입 / NULL</th></tr>${t.columns.map(c=>`<tr><td>${esc(c.name)}<br><small>${esc(c.label)}</small></td><td>${esc(c.type)}${c.nullable?' / 허용':' / 불가'}</td></tr>`).join('')}</table><h3>외래키 ${rs.length}개</h3>${rs.map(r=>`<pre>${esc(r.source)}\n(${esc(r.columns.join(', '))})\n → ${esc(r.target)}\n(${esc(r.target_columns.join(', '))})\n${esc(r.note)}</pre>`).join('')}`}
draw();</script></html>'''
page=page.replace('__VERSION__',html.escape(d['version'])).replace('__DATA__',data).replace('__MODS__',json.dumps(mods,ensure_ascii=False))
(out/'EIP_모듈별_ERD.html').write_text(page)
(out/'README.md').write_text('# '+d['task']+' 독립 솔루션별 ERD\n\n`EIP_모듈별_ERD.html`은 외부 라이브러리 없이 여는 SVG 관계 탐색기다. EIP→모듈 구성과 FK 관계를 구분한다.\n\n전체 및 4스키마 Mermaid 원본은 `.mmd` 파일로 제공한다. 각 관계는 참조 대상 0..1/1 및 자식 0..1/다수를 NULL·UNIQUE에서 유도했다. 모든 SQL은 아직 미적용이다. 서비스 정책은 선으로 증명되지 않는다.\n\n기준 해시: '+hashlib.sha256(p.read_bytes()).hexdigest()+'\n')
print(f'Generated: offline explorer, {len(mods)} Mermaid ERDs + all, README')
